exercise.solution:
class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def describe(self):
        print(f"Rectangle: {self.width}x{self.height}, Area: {self.area()}, Perimeter: {self.perimeter()}")

rect = Rectangle(5, 3)
print(rect.area())
print(rect.perimeter())
rect.describe()
